using Factory = std::function<std::shared_ptr<Repository>()>;

class Locator {
    std::unordered_map<std::string, Factory> factories_;
public:
    void set(const std::string& name, Factory f) { factories_[name] = std::move(f); }
    std::shared_ptr<Repository> get(const std::string& name) const {
        auto it = factories_.find(name);
        if (it == factories_.end()) throw std::runtime_error("unregistered: " + name);
        return it->second();
    }
};
